// Normalize one Apollo person into a lead shape and fetch their site
const p = $json;
const org = p.organization || {};
const website = org.website_url || (org.primary_domain ? `https://${org.primary_domain}` : null);

if (!website || !p.email) {
  return { json: { skip: true, reason: 'no website or email', person: p } };
}

let html = '';
let detected = [];
let fetchError = null;
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: website,
    timeout: 15000,
    returnFullResponse: false,
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; LodgeQualifier/1.0)' }
  });
  html = (typeof res === 'string' ? res : JSON.stringify(res)).toLowerCase();
} catch (e) {
  fetchError = e.message;
}

const signatures = {
  checkfront: ['checkfront.com', 'cfwidget'],
  resnexus:   ['resnexus.com'],
  fareharbor: ['fareharbor.com', 'fh-button'],
  bookeo:     ['bookeo.com'],
  cloudbeds:  ['cloudbeds.com', 'mybookings.cloudbeds'],
  lodgify:    ['lodgify.com'],
  thinkres:   ['thinkreservations.com'],
  innroad:    ['innroad.com'],
  rezdy:      ['rezdy.com'],
  peek:       ['peekpro.com', 'bookwithpeek'],
  webrez:     ['webrezpro.com'],
  resharmonics:['resharmonics.com'],
};
for (const [name, needles] of Object.entries(signatures)) {
  if (needles.some(n => html.includes(n))) detected.push(name);
}

const booking_widget_detected = detected.length > 0;

return {
  json: {
    skip: false,
    business_name: org.name || p.name || 'Unknown',
    contact_name: p.name || null,
    email: p.email,
    phone: org.phone || null,
    city: p.city || org.city || null,
    state: p.state || org.state || null,
    website,
    booking_widget_detected,
    detected_widgets: detected,
    fetch_error: fetchError,
    html_snippet: html.slice(0, 3000),
    title: p.title || null,
    source: 'apollo+n8n'
  }
};

values.content:
=You are writing ONE opening sentence for a cold email to a fishing lodge owner.

Business: {{$json.business_name}}
Location: {{$json.city}}, {{$json.state}}
Website text snippet: {{$json.html_snippet}}

Write a single sentence (under 25 words) that feels personal and specific to their lodge. Reference something real from the snippet — a species, a lake, a guide, an experience. Do NOT mention websites, booking, software, or sales. Just a warm opener. Output only the sentence, no quotes, no prefix.

